import hashlib, json
from pathlib import Path
root = Path('products/distribution/sqlite-community-directory')
expected = {'operator-submission-packet.md': 'e96a98a22124ba63287c3047da95b0adcc073077d23e52a4d0e368830afbc0b4', 'director-referral-candidate.diff': '1017529e2e4b4268992686b690268b13d3c4d3ca5d7e98195a853833314360d8'}
bindings = {}
for name, digest in expected.items():
    path = root / name
    actual = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
    bindings[name] = {'expected': digest, 'actual': actual, 'matches': actual == digest}
pointers = []
for path in sorted(root.rglob('*')):
    if not path.is_file() or path.suffix not in {'.md', '.json', '.txt'} or path.stat().st_size > 262144 or path.name == 'director-referral-decision-index.json':
        continue
    payload = path.read_bytes()
    if all(value.encode() in payload for value in expected.values()):
        pointers.append(str(path))
result = {'bindings': bindings, 'candidate_records_containing_both_hashes': pointers, 'coverage': 'Selected public directory only. Matching text is a pointer. Verify the author, verdict and operator authority in the original record before acting.'}
out = root / 'director-referral-decision-index.json'
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
